package com.alsafa.native4;import android.app.Activity;import android.content.Intent;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import com.alsafa.native4.core.*;import java.util.*;
public final class SearchActivity extends Activity{private CoreDb db;private CoreProductCatalog catalog;private EditText query;private LinearLayout results;private TextView status;private final Handler h=new Handler(Looper.getMainLooper());private final Runnable run=this::search;
@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_search);db=new CoreDb(this);catalog=new CoreProductCatalog(db);query=findViewById(R.id.globalSearch);results=findViewById(R.id.globalResults);status=findViewById(R.id.searchStatus);query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){h.removeCallbacks(run);h.postDelayed(run,325);}public void afterTextChanged(Editable e){}});Nav5.bind(this,R.id.navSearch);query.requestFocus();}
private void search(){String q=query.getText().toString().trim();results.removeAllViews();if(q.isEmpty()){status.setText("ابدأ الكتابة للبحث");return;}List<CoreProductCatalog.ProductHit> rows=catalog.search(q,50);status.setText("النتائج: "+rows.size());for(CoreProductCatalog.ProductHit p:rows){TextView t=new TextView(this);t.setGravity(Gravity.END);t.setPadding(dp(12),dp(12),dp(12),dp(12));t.setBackgroundResource(R.drawable.alsafa_card);t.setText(p.name+(p.ref.isEmpty()?"":" — "+p.ref)+(p.barcode.isEmpty()?"":"\nباركود: "+p.barcode)+"\nالمتوفر: "+p.quantity+" — "+String.format(Locale.US,"%.2f",p.salePrice)+" "+p.currency);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.setMargins(0,dp(5),0,dp(5));results.addView(t,lp);}}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}@Override protected void onDestroy(){h.removeCallbacks(run);super.onDestroy();}}
